export interface Hotspot3D {
  id: string;
  pinNumber: number;
  position: [number, number, number];
  color: string;
  badgeLabel?: string;
  title: LocalizedText;
  description: LocalizedText;
  examFact: LocalizedText;
  // Backward compatibility fields for E2E harness
  name: LocalizedText;
  role: LocalizedText;
  quickHint: LocalizedText;
  osymExamFact: LocalizedText;
}

export interface ChemicalSceneSpec {
  id: string;
  unitId: string;
  badge: 'TYT' | 'AYT';
  title: LocalizedText;
  subtitle: LocalizedText;
  description: LocalizedText;
  category: 'vsepr' | 'crystal' | 'electrochem' | 'organic' | 'atomic' | 'gas_solution' | 'general';
  geometryType: string;
  cameraPosition: [number, number, number];
  target?: [number, number, number];
  cameraConstraints?: OrbitCameraConstraints;
  explodeConstraints?: ExplodeViewConstraints;
  latticeSpec?: CrystalLatticeSpec;
  hotspots: Hotspot3D[];
  build: (isDark: boolean) => ProceduralSceneObject;
  builder: (container: any, isDark: boolean) => {
    animate: (time: number) => void;
    dispose: () => void;
  };
  aliases?: string[];
}

function createBuilderAdapter(sceneId: string) {
  return (_container: any, isDark: boolean) => {
    const builderFn = PROCEDURAL_BUILDERS[sceneId] || PROCEDURAL_BUILDERS['u01-fractional-distillation'];
    const obj = builderFn(isDark);
    return {
      animate: (time: number) => { if (obj.animate) obj.animate(time, true); },
      dispose: () => { if (obj.dispose) obj.dispose(); },
    };
  };
}

