        role: { tr: "Liebig Soğutucusu", en: "Liebig Condenser", de: "Liebigkühler", fr: "Réfrigérant de Liebig", ru: "Холодильник Либиха", ar: "مكثف ليبيغ", zh: "李比希冷凝管", ku: "Sarisoxera Liebig" },
