    title: { tr: "Karbondioksit Doğrusal Geometri ve Sera Etkisi", en: "Carbon Dioxide Linear Molecule & Greenhouse Effect", de: "Kohlenstoffdioxid: Lineare Geometrie und Treibhauseffekt", fr: "Dioxyde de carbone : molécule linéaire et effet de serre", ru: "Диоксид углерода: линейная геометрия и парниковый эффект", ar: "ثاني أكسيد الكربون: هندسة خطية وتأثير الاحتباس الحراري", zh: "二氧化碳直线形分子几何与红外温室效应", ku: "Karbondioksît: Geometriya Rast û Bandora Serayê" },
    subtitle: { tr: "VSEPR AX₂ Geometrisi, 180° Bağ Açısı ve IR Titreşim Modları", en: "VSEPR AX₂ Geometry, 180° Bond Angle and IR Vibration Modes", de: "VSEPR AX₂-Geometrie, 180°-Winkel und IR-Schwingungsmoden", fr: "Géométrie VSEPR AX₂, angle de 180° et modes de vibration IR", ru: "Геометрия VSEPR AX₂, угол 180° и моды колебаний ИК", ar: "هندسة AX₂ الخطية بزاوية 180° وأنماط الاهتزاز تحت الحمراء", zh: "VSEPR AX₂线形构型、180°键角与红外不对称弯曲吸收", ku: "Geometriya VSEPR AX₂, Goşeya 180° û Livên IR" },
    description: { tr: "VSEPR AX₂ Geometrisi, 180° Bağ Açısı ve IR Titreşim Modları", en: "VSEPR AX₂ Geometry, 180° Bond Angle and IR Vibration Modes", de: "VSEPR AX₂-Geometrie, 180°-Winkel und IR-Schwingungsmoden", fr: "Géométrie VSEPR AX₂, angle de 180° et modes de vibration IR", ru: "Геометрия VSEPR AX₂, угол 180° и моды колебаний ИК", ar: "هندسة AX₂ الخطية بزاوية 180° وأنماط الاهتزاز تحت الحمراء", zh: "VSEPR AX₂线形构型、180°键角与红外不对称弯曲吸收", ku: "Geometriya VSEPR AX₂, Goşeya 180° û Livên IR" },
    category: 'vsepr',
