      {
        id: 'u07-hs3',
        pinNumber: 3,
        position: [-1.2, 0.5, 0.0],
        color: '#38bdf8',
        badgeLabel: "Yanma ΔH<0",
        title: { tr: "Metanın Yanması (CH₄ + 2 O₂ → CO₂ + 2 H₂O)", en: "Methane Combustion (CH₄ + 2 O₂ → CO₂ + 2 H₂O)", de: "Methanverbrennung (CH₄ + 2 O₂ → CO₂ + 2 H₂O)", fr: "Combustion du méthane (CH₄ + 2 O₂ → CO₂ + 2 H₂O)", ru: "Горение метана (CH₄ + 2 O₂ → CO₂ + 2 H₂O)", ar: "احتراق الميثان (CH₄ + 2 O₂ → CO₂ + 2 H₂O)", zh: "甲烷完全燃烧反应（CH₄ + 2 O₂ → CO₂ + 2 H₂O）", ku: "Şewitîna Mêtanê (CH₄ + 2 O₂ → CO₂ + 2 H₂O)" },
        description: { tr: "Doğal gazın ana bileşeni olan metan, oksijenle ekzotermik yanma tepkimesi verir: CH₄(g) + 2 O₂(g) → CO₂(g) + 2 H₂O(s) + 890 kJ. 1 mol CH₄ yandığında 890 kJ ısı açığa çıkar.", en: "Complete combustion of methane releases 890 kJ/mol of heat: CH₄(g) + 2 O₂(g) → CO₂(g) + 2 H₂O(l) + 890 kJ. Highly exothermic reaction driving domestic gas heating.", de: "Die Verbrennung von Methan setzt 890 kJ/mol Wärme frei: CH₄(g) + 2 O₂(g) → CO₂(g) + 2 H₂O(l) + 890 kJ.", fr: "La combustion complète du méthane dégage 890 kJ/mol : CH₄(g) + 2 O₂(g) → CO₂(g) + 2 H₂O(l) + 890 kJ.", ru: "Полное сгорание метана сопровождается выделением 890 кДж/моль тепла: CH₄(g) + 2 O₂(g) → CO₂(g) + 2 H₂O(ж) + 890 кДж.", ar: "الاحتراق التام للميثان ينتج حرارة هائلة: CH₄(g) + 2 O₂(g) → CO₂(g) + 2 H₂O(l) + 890 kJ.", zh: "天然气主要成分甲烷完全燃烧强烈放热：CH₄(g) + 2 O₂(g) → CO₂(g) + 2 H₂O(l) + 890 kJ。1摩尔甲烷完全燃烧释放890 kJ能量。", ku: "Pêkhateya sereke ya gaza xwezayî mêtan e ku bi oksîjenê re dişewite û 890 kJ germî dide der." },
        examFact: { tr: "ÖSYM Stokiyometri Sorusu: 1 mol CH₄'ü tamamen yakmak için NŞA'da tam 2 mol (44.8 L) O₂ gazı gerekir. Havanın 1/5'i oksijen olduğuna göre 1 mol metan için 10 mol (224 L) hava harcanır!", en: "Classic Stoichiometry Calculation: To completely burn 1 mol of CH₄, exactly 2 mol (44.8 L at STP) of O₂ is consumed. Since air is 20% oxygen by volume, exactly 10 mol (224 L) of air is required!", de: "Stöchiometrie-Klassiker: Zur Verbrennung von 1 Mol CH₄ werden 2 Mol (44,8 L) O₂ benötigt. Bei 20% O₂ in der Luft erfordert dies 10 Mol (224 L) Luft!", fr: "Calcul stœchiométrique classique: 1 mol de CH₄ consomme 2 mol (44,8 L à CNTP) de O₂. L'air contenant 20% de O₂, il faut 10 mol (224 L) d'air !", ru: "Классический стехиометрический расчет: Для сжигания 1 моль CH₄ требуется 2 моль (44.8 л) O₂, что соответствует 10 моль (224 л) воздуха!", ar: "مسألة حسابية كلاسيكية: لاحتراق 1 مول من الميثان يلزم 2 مول (44.8 لتر) من O₂. وبما أن نسبة الأكسجين في الهواء 20%، يلزم 10 مول (224 لتر) من الهواء!", zh: "经典化学计量考题：完全燃烧1 mol CH₄恰好消耗2 mol（标准状况下44.8 L）O₂。由于空气中氧气约占1/5，故实际需消耗10 mol（224 L）空气！", ku: "Hesabkirina Stokiyometrîk: Ji bo şewitandina 1 mol CH₄ 2 mol (44.8 L) gaza O₂ pêwîst e; ev jî dike 224 L hewa!" },
        name: { tr: "Metanın Yanması (CH₄ + 2 O₂ → CO₂ + 2 H₂O)", en: "Methane Combustion (CH₄ + 2 O₂ → CO₂ + 2 H₂O)", de: "Methanverbrennung (CH₄ + 2 O₂ → CO₂ + 2 H₂O)", fr: "Combustion du méthane (CH₄ + 2 O₂ → CO₂ + 2 H₂O)", ru: "Горение метана (CH₄ + 2 O₂ → CO₂ + 2 H₂O)", ar: "احتراق الميثان (CH₄ + 2 O₂ → CO₂ + 2 H₂O)", zh: "甲烷完全燃烧反应（CH₄ + 2 O₂ → CO₂ + 2 H₂O）", ku: "Şewitîna Mêtanê (CH₄ + 2 O₂ → CO₂ + 2 H₂O)" },
        role: { tr: "Metanın Yanması (CH₄ + 2 O₂ → CO₂ + 2 H₂O)", en: "Methane Combustion (CH₄ + 2 O₂ → CO₂ + 2 H₂O)", de: "Methanverbrennung (CH₄ + 2 O₂ → CO₂ + 2 H₂O)", fr: "Combustion du méthane (CH₄ + 2 O₂ → CO₂ + 2 H₂O)", ru: "Горение метана (CH₄ + 2 O₂ → CO₂ + 2 H₂O)", ar: "احتراق الميثان (CH₄ + 2 O₂ → CO₂ + 2 H₂O)", zh: "甲烷完全燃烧反应（CH₄ + 2 O₂ → CO₂ + 2 H₂O）", ku: "Şewitîna Mêtanê (CH₄ + 2 O₂ → CO₂ + 2 H₂O)" },
        quickHint: { tr: "Metanın Yanması (CH₄ + 2 O₂ → CO₂ + 2 H₂O)", en: "Methane Combustion (CH₄ + 2 O₂ → CO₂ + 2 H₂O)", de: "Methanverbrennung (CH₄ + 2 O₂ → CO₂ + 2 H₂O)", fr: "Combustion du méthane (CH₄ + 2 O₂ → CO₂ + 2 H₂O)", ru: "Горение метана (CH₄ + 2 O₂ → CO₂ + 2 H₂O)", ar: "احتراق الميثان (CH₄ + 2 O₂ → CO₂ + 2 H₂O)", zh: "甲烷完全燃烧反应（CH₄ + 2 O₂ → CO₂ + 2 H₂O）", ku: "Şewitîna Mêtanê (CH₄ + 2 O₂ → CO₂ + 2 H₂O)" },
        osymExamFact: { tr: "ÖSYM Stokiyometri Sorusu: 1 mol CH₄'ü tamamen yakmak için NŞA'da tam 2 mol (44.8 L) O₂ gazı gerekir. Havanın 1/5'i oksijen olduğuna göre 1 mol metan için 10 mol (224 L) hava harcanır!", en: "Classic Stoichiometry Calculation: To completely burn 1 mol of CH₄, exactly 2 mol (44.8 L at STP) of O₂ is consumed. Since air is 20% oxygen by volume, exactly 10 mol (224 L) of air is required!", de: "Stöchiometrie-Klassiker: Zur Verbrennung von 1 Mol CH₄ werden 2 Mol (44,8 L) O₂ benötigt. Bei 20% O₂ in der Luft erfordert dies 10 Mol (224 L) Luft!", fr: "Calcul stœchiométrique classique: 1 mol de CH₄ consomme 2 mol (44,8 L à CNTP) de O₂. L'air contenant 20% de O₂, il faut 10 mol (224 L) d'air !", ru: "Классический стехиометрический расчет: Для сжигания 1 моль CH₄ требуется 2 моль (44.8 л) O₂, что соответствует 10 моль (224 л) воздуха!", ar: "مسألة حسابية كلاسيكية: لاحتراق 1 مول من الميثان يلزم 2 مول (44.8 لتر) من O₂. وبما أن نسبة الأكسجين في الهواء 20%، يلزم 10 مول (224 لتر) من الهواء!", zh: "经典化学计量考题：完全燃烧1 mol CH₄恰好消耗2 mol（标准状况下44.8 L）O₂。由于空气中氧气约占1/5，故实际需消耗10 mol（224 L）空气！", ku: "Hesabkirina Stokiyometrîk: Ji bo şewitandina 1 mol CH₄ 2 mol (44.8 L) gaza O₂ pêwîst e; ev jî dike 224 L hewa!" },
      }
