    subtitle: { tr: "VSEPR AX₃E Geometrisi, 107.3° Bağ Açısı ve Proton Yakalama", en: "VSEPR AX₃E Geometry, 107.3° Bond Angle & Proton Acceptance", de: "VSEPR AX₃E-Geometrie, 107,3°-Winkel und Protonenakzeptanz", fr: "Géométrie VSEPR AX₃E, angle de 107,3° et captation de proton", ru: "Геометрия VSEPR AX₃E, угол 107.3° и присоединение протона", ar: "هندسة AX₃E بزاوية 107.3° وقبول البروتونات", zh: "VSEPR AX₃E几何构型、107.3°压缩键角与配位质子化反应", ku: "Geometriya VSEPR AX₃E, Goşeya 107.3° û Girtina Protonê" },
    description: { tr: "VSEPR AX₃E Geometrisi, 107.3° Bağ Açısı ve Proton Yakalama", en: "VSEPR AX₃E Geometry, 107.3° Bond Angle & Proton Acceptance", de: "VSEPR AX₃E-Geometrie, 107,3°-Winkel und Protonenakzeptanz", fr: "Géométrie VSEPR AX₃E, angle de 107,3° et captation de proton", ru: "Геометрия VSEPR AX₃E, угол 107.3° и присоединение протона", ar: "هندسة AX₃E بزاوية 107.3° وقبول البروتونات", zh: "VSEPR AX₃E几何构型、107.3°压缩键角与配位质子化反应", ku: "Geometriya VSEPR AX₃E, Goşeya 107.3° û Girtina Protonê" },
