      {
        id: 'u12-hs6',
        pinNumber: 3,
        position: [0.38, 0.0, 0.0],
        color: '#38bdf8',
        badgeLabel: "NH₄Cl Halkası",
        title: { tr: "Amonyum Klorür (NH₄Cl) Beyaz Duman Halkası", en: "Ammonium Chloride (NH₄Cl) White Smoke Ring", de: "Ammoniumchlorid (NH₄Cl) weißer Rauchring", fr: "Anneau de fumée blanche de chlorure d'ammonium (NH₄Cl)", ru: "Белое кольцо дыма хлорида аммония (NH₄Cl)", ar: "حلقة الدخان البيضاء لكلوريد الأمونيوم (NH₄Cl)", zh: "氯化铵（NH₄Cl）固体沉淀白烟环生成位置", ku: "Xeleka Dûyê ya Spî ya Amonyûm Klorurê (NH₄Cl)" },
        description: { tr: "İki gazın karşılaştığı noktada anında katı çökelek oluşur: NH₃(g) + HCl(g) → NH₄Cl(k). 100 cm'lik bir tüpte NH₃ 59.5 cm yol alırken, HCl sadece 40.5 cm yol alır; bu nedenle halka HCl ucuna daha yakın oluşur.", en: "At the meeting point, white solid ammonium chloride precipitates immediately: NH₃(g) + HCl(g) → NH₄Cl(s). In a 100 cm tube, NH₃ travels 59.5 cm while HCl travels 40.5 cm; the ring forms closer to the heavier HCl end.", de: "Am Treffpunkt entsteht weißer NH₄Cl-Rauch. In einem 100-cm-Rohr legt NH₃ 59,5 cm zurück, HCl nur 40,5 cm.", fr: "La fumée blanche de NH₄Cl précipite au point de rencontre. Sur 100 cm, NH₃ parcourt 59,5 cm et HCl 40,5 cm.", ru: "В точке встречи мгновенно образуется белый налет: NH₃(г) + HCl(г) → NH₄Cl(тв). На 100 см трубки NH₃ проходит 59.5 см, а HCl — 40.5 см.", ar: "تتكون حلقة دخان بيضاء صلبة عند نقطة اللقاء: NH₃(g) + HCl(g) → NH₄Cl(s)؛ وفي أنبوب طوله 100 سم تقطع الأمونيا 59.5 سم بينما يقطع HCl مسافة 40.5 سم فقط، لذا تقترب الحلقة من طرف HCl الأثقل.", zh: "两种无色气体相遇瞬间发生酸碱化合生成白色固体颗粒并形成白烟环：NH₃(g) + HCl(g) → NH₄Cl(s)。在100厘米长的玻璃管中，较轻的NH₃移动59.5 cm，较重的HCl仅移动40.5 cm，故白烟环偏向HCl一端。", ku: "Li cihê ku her du gaz rastî hev tên dûyek spî çêdibe: NH₃(g) + HCl(g) → NH₄Cl(k). Ji ber ku NH₃ zûtir diçe, xelek nêzîkî serê HCl çêdibe." },
        examFact: { tr: "ÖSYM Tarzı Soru: 40 cm uzunluğundaki cam tüpte aynı anda bırakılan gazların nerede karşılaşacağı sorulabilir: x_NH3 / x_HCl = 1.465 oranından x_NH3 ≈ 23.8 cm, x_HCl ≈ 16.2 cm hesaplanır. Karşılaşma noktası daima ağır olan gaza daha yakındır!", en: "ÖSYM-Style Question: In a 40 cm tube, where do they meet? Using the speed ratio 1.465: x_NH3 = 23.8 cm and x_HCl = 16.2 cm. The ring ALWAYS forms closer to the heavier gas source!", de: "Prüfungsfrage im ÖSYM-Stil: Bei einem 40-cm-Rohr treffen sie sich bei 23,8 cm von NH₃ und 16,2 cm von HCl. Der Treffpunkt liegt immer näher am schwereren Gas!", fr: "Question de type ÖSYM : Dans un tube de 40 cm, la rencontre a lieu à 23,8 cm de NH₃ et 16,2 cm de HCl. Le point de rencontre est toujours plus proche du gaz lourd !", ru: "Вопрос в стиле ÖSYM: В трубке длиной 40 см газы встречаются на расстоянии 23.8 см от NH₃ и 16.2 см от HCl. Точка встречи ВСЕГДА ближе к более тяжелому газу!", ar: "سؤال بأسلوب ÖSYM: في أنبوب طوله 40 سم يلتقي الغازان على بعد 23.8 سم من طرف الأمونيا و 16.2 سم من طرف HCl؛ نقطة الالتقاء دائماً أقرب إلى الغاز الأثقل!", zh: "ÖSYM风格例题：在长40 cm的玻璃管中两端同时释放气体，由于速率比为1.465，求得相遇点距氨气端23.8 cm，距盐酸端16.2 cm。核心规律：相遇沉淀点永远靠近分子量较大（扩散较慢）的一端！", ku: "Pirsa bi şêwaza ÖSYM: Di lûleya 40 cm de cihê hevdîtinê nêzîkî gaza girantir (HCl) e (ji NH₃ 23.8 cm, ji HCl 16.2 cm)." },
        name: { tr: "Amonyum Klorür (NH₄Cl) Beyaz Duman Halkası", en: "Ammonium Chloride (NH₄Cl) White Smoke Ring", de: "Ammoniumchlorid (NH₄Cl) weißer Rauchring", fr: "Anneau de fumée blanche de chlorure d'ammonium (NH₄Cl)", ru: "Белое кольцо дыма хлорида аммония (NH₄Cl)", ar: "حلقة الدخان البيضاء لكلوريد الأمونيوم (NH₄Cl)", zh: "氯化铵（NH₄Cl）固体沉淀白烟环生成位置", ku: "Xeleka Dûyê ya Spî ya Amonyûm Klorurê (NH₄Cl)" },
        role: { tr: "Amonyum Klorür (NH₄Cl) Beyaz Duman Halkası", en: "Ammonium Chloride (NH₄Cl) White Smoke Ring", de: "Ammoniumchlorid (NH₄Cl) weißer Rauchring", fr: "Anneau de fumée blanche de chlorure d'ammonium (NH₄Cl)", ru: "Белое кольцо дыма хлорида аммония (NH₄Cl)", ar: "حلقة الدخان البيضاء لكلوريد الأمونيوم (NH₄Cl)", zh: "氯化铵（NH₄Cl）固体沉淀白烟环生成位置", ku: "Xeleka Dûyê ya Spî ya Amonyûm Klorurê (NH₄Cl)" },
        quickHint: { tr: "Amonyum Klorür (NH₄Cl) Beyaz Duman Halkası", en: "Ammonium Chloride (NH₄Cl) White Smoke Ring", de: "Ammoniumchlorid (NH₄Cl) weißer Rauchring", fr: "Anneau de fumée blanche de chlorure d'ammonium (NH₄Cl)", ru: "Белое кольцо дыма хлорида аммония (NH₄Cl)", ar: "حلقة الدخان البيضاء لكلوريد الأمونيوم (NH₄Cl)", zh: "氯化铵（NH₄Cl）固体沉淀白烟环生成位置", ku: "Xeleka Dûyê ya Spî ya Amonyûm Klorurê (NH₄Cl)" },
        osymExamFact: { tr: "ÖSYM Tarzı Soru: 40 cm uzunluğundaki cam tüpte aynı anda bırakılan gazların nerede karşılaşacağı sorulabilir: x_NH3 / x_HCl = 1.465 oranından x_NH3 ≈ 23.8 cm, x_HCl ≈ 16.2 cm hesaplanır. Karşılaşma noktası daima ağır olan gaza daha yakındır!", en: "ÖSYM-Style Question: In a 40 cm tube, where do they meet? Using the speed ratio 1.465: x_NH3 = 23.8 cm and x_HCl = 16.2 cm. The ring ALWAYS forms closer to the heavier gas source!", de: "Prüfungsfrage im ÖSYM-Stil: Bei einem 40-cm-Rohr treffen sie sich bei 23,8 cm von NH₃ und 16,2 cm von HCl. Der Treffpunkt liegt immer näher am schwereren Gas!", fr: "Question de type ÖSYM : Dans un tube de 40 cm, la rencontre a lieu à 23,8 cm de NH₃ et 16,2 cm de HCl. Le point de rencontre est toujours plus proche du gaz lourd !", ru: "Вопрос в стиле ÖSYM: В трубке длиной 40 см газы встречаются на расстоянии 23.8 см от NH₃ и 16.2 см от HCl. Точка встречи ВСЕГДА ближе к более тяжелому газу!", ar: "سؤال بأسلوب ÖSYM: في أنبوب طوله 40 سم يلتقي الغازان على بعد 23.8 سم من طرف الأمونيا و 16.2 سم من طرف HCl؛ نقطة الالتقاء دائماً أقرب إلى الغاز الأثقل!", zh: "ÖSYM风格例题：在长40 cm的玻璃管中两端同时释放气体，由于速率比为1.465，求得相遇点距氨气端23.8 cm，距盐酸端16.2 cm。核心规律：相遇沉淀点永远靠近分子量较大（扩散较慢）的一端！", ku: "Pirsa bi şêwaza ÖSYM: Di lûleya 40 cm de cihê hevdîtinê nêzîkî gaza girantir (HCl) e (ji NH₃ 23.8 cm, ji HCl 16.2 cm)." },
      }
