    title: { tr: "Aktifleşmiş Kompleks ve Geçiş Hali Potansiyel Enerjisi", en: "Activated Complex & Transition State Potential Energy", de: "Aktivierter Komplex und Übergangszustand", fr: "Complexe activé et énergie potentielle de l'état de transition", ru: "Активированный комплекс и переходное состояние", ar: "المعقد المنشط وطاقة وضع الحالة الانتقالية", zh: "活化络合物过渡态高能模型与活化能势能曲线", ku: "Kompleksa Çalakbûyî û Rewşa Derbasbûnê" },
    subtitle: { tr: "Çarpışma Teorisi, İleri/Geri Aktivasyon Enerjisi ve [O=N···O···C=O]‡ Yapısı", en: "Collision Theory, Forward/Reverse Activation Energy & Transition State", de: "Stoßtheorie, Aktivierungsenergie und Übergangszustand", fr: "Théorie des collisions et barrière d'activation", ru: "Теория столкновений и барьер энергии активации", ar: "نظرية التصادمات، طاقة التنشيط وهيكل الحالة الانتقالية", zh: "碰撞理论有效碰撞取向、正逆活化能势垒与过渡态构型", ku: "Teoriya Pevketinê û Astengiya Enerjiya Çalakbûnê" },
    description: { tr: "Çarpışma Teorisi, İleri/Geri Aktivasyon Enerjisi ve [O=N···O···C=O]‡ Yapısı", en: "Collision Theory, Forward/Reverse Activation Energy & Transition State", de: "Stoßtheorie, Aktivierungsenergie und Übergangszustand", fr: "Théorie des collisions et barrière d'activation", ru: "Теория столкновений и барьер энергии активации", ar: "نظرية التصادمات، طاقة التنشيط وهيكل الحالة الانتقالية", zh: "碰撞理论有效碰撞取向、正逆活化能势垒与过渡态构型", ku: "Teoriya Pevketinê û Astengiya Enerjiya Çalakbûnê" },
