    subtitle: { tr: "Zn/Cu Standart Elektrot Potansiyelleri (E° = +1.10 V) ve İyon Göçü", en: "Zn/Cu Standard Cell Potential (E° = +1.10 V) & Redox Dynamics", de: "Standard-Zellpotenzial (E° = 1,10 V) und Redoxdynamik", fr: "Potentiel standard de pile (E° = +1,10 V) et flux d'électrons", ru: "Стандартный потенциал элемента (E° = +1.10 В) и поток электронов", ar: "جهد الخلية القياسي (E° = +1.10 V) وانتقال الإلكترونات والأيونات", zh: "锌阳极氧化溶解与铜阴极还原沉积及Nernst自发电动势", ku: "Potansiyela Standard a Pîlê (E° = +1.10 V) û Herikîna Elektronan" },
    description: { tr: "Zn/Cu Standart Elektrot Potansiyelleri (E° = +1.10 V) ve İyon Göçü", en: "Zn/Cu Standard Cell Potential (E° = +1.10 V) & Redox Dynamics", de: "Standard-Zellpotenzial (E° = 1,10 V) und Redoxdynamik", fr: "Potentiel standard de pile (E° = +1,10 V) et flux d'électrons", ru: "Стандартный потенциал элемента (E° = +1.10 В) и поток электронов", ar: "جهد الخلية القياسي (E° = +1.10 V) وانتقال الإلكترونات والأيونات", zh: "锌阳极氧化溶解与铜阴极还原沉积及Nernst自发电动势", ku: "Potansiyela Standard a Pîlê (E° = +1.10 V) û Herikîna Elektronan" },
