      {
        id: 'u24-hs3',
        pinNumber: 3,
        position: [1.4, 0.0, 0.0],
        color: '#38bdf8',
        badgeLabel: "Aromatiklik",
        title: { tr: "Aromatik Bileşikler ve Bromlu Su Testi", en: "Aromatic Chemistry & Bromine Water Reaction Test", de: "Aromatische Chemie und Bromwassertest", fr: "Chimie aromatique et test à l'eau de brome", ru: "Ароматические соединения и проба с бромной водой", ar: "المركبات العطرية واختبار ماء البروم", zh: "芳香族化合物与溴水褪色鉴别特征反应", ku: "Pêkhateyên Aromadîk û Ceribandina bi Ava Bromê" },
        description: { tr: "Benzen halkası içeren bileşiklere 'Aromatik Bileşikler' (Arenler) denir. Alkenlerin aksine benzen, oda koşullarında bromlu suyun kırmızı-kahverengi rengini gidermez. Yalnızca FeBr₃ gibi kuvvetli Lewis asidi katalizörlüğünde elektrofilik sübstitüsyonla bromobenzen verir.", en: "Compounds containing a benzene ring are 'Aromatics' (Arenes). Unlike alkenes, benzene DOES NOT decolorize bromine water at room temperature. It only reacts via electrophilic substitution in the presence of a FeBr3 Lewis acid catalyst.", de: "Aromaten entfärben im Gegensatz zu Alkenen kein Bromwasser ohne Katalysator (FeBr₃).", fr: "Les arènes ne décolorent pas l'eau de brome à température ambiante, contrairement aux alcènes.", ru: "Ароматические углеводороды (арены) не обесцвечивают бромную воду без катализатора (FeBr₃), в отличие от алкенов.", ar: "المركبات التي تحوي حلقة بنزين تسمى مركبات عطرية؛ وخلافاً للألكينات لا يزيل البنزين لون ماء البروم في الظروف العادية إلا بوجود محفز FeBr₃ تفاعل استبدال.", zh: "含有苯环结构的烃类统称为“芳香烃”（Arenes）。与普通烯烃形成鲜明对比的是：常温下苯不能使溴水褪色（不发生加成反应）。只有在强路易斯酸催化剂（如FeBr₃）存在下，苯才与液溴发生亲电取代反应生成溴苯。", ku: "Pêkhateyên ku xeleka benzenê dihewînin 'Aromadîk' in. Berevajî alkenan, ava bromê bêyî katalîzor bêreng nakin." },
        examFact: { tr: "ÖSYM Ayıraç Tuzağı: Alkenler ve alkinler bromlu suyun rengini oda koşullarında katılarak GİDERİR; benzen ise bromlu suyun rengini GİDERMEZ! ÖSYM organik soru köklerinde bu ayıraç farkını hidrokarbon sınıfını tespit etmek için kilit ipucu olarak verir.", en: "Bromine Water Diagnostic Trap: Alkenes and alkynes rapidly decolorize bromine water via addition at room temperature; BENZENE DOES NOT decolorize bromine water! This test distinguishes aliphatic unsaturated hydrocarbons from aromatic rings.", de: "Diagnostischer Prüfungsfakt: Alkene und Alkine entfärben Bromwasser sofort; BENZOL ENT FÄRBT ES NICHT!", fr: "Différenciation d'examen : Alcènes et alcynes décolorent l'eau de brome instantanément ; LE BENZÈNE NE LA DÉCOLORE PAS !", ru: "Диагностический признак экзамена: Алкены и алкины обесцвечивают бромную воду; БЕНЗОЛ НЕ ОБЕСЦВЕЧИВАЕТ БРОМНУЮ ВОДУ!", ar: "فخ امتحاني تشخيصي: الألكينات والألكاينات تزيل لون ماء البروم سريعاً بتفاعل الإضافة؛ بينما البنزين لا يزيل لون ماء البروم مطلقاً في هذه الظروف!", zh: "高考有机化合物鉴别核心路标考点：含有碳碳双键或三键的脂肪族不饱和烃（烯烃、炔烃）在常温常压下极易与溴发生加成反应使溴水完全褪色；而苯分子由于大π键超常稳定性，常温下绝不使溴水褪色！这是高考推断题识别苯环的绝对关键标志！", ku: "Xefika Naskirina YKS: Alken û alkîn di germahiya odeyê de ava bromê bêreng dikin; lê benzen AVA BROMÊ BÊRENG NAKE!" },
        name: { tr: "Aromatik Bileşikler ve Bromlu Su Testi", en: "Aromatic Chemistry & Bromine Water Reaction Test", de: "Aromatische Chemie und Bromwassertest", fr: "Chimie aromatique et test à l'eau de brome", ru: "Ароматические соединения и проба с бромной водой", ar: "المركبات العطرية واختبار ماء البروم", zh: "芳香族化合物与溴水褪色鉴别特征反应", ku: "Pêkhateyên Aromadîk û Ceribandina bi Ava Bromê" },
        role: { tr: "Aromatik Bileşikler ve Bromlu Su Testi", en: "Aromatic Chemistry & Bromine Water Reaction Test", de: "Aromatische Chemie und Bromwassertest", fr: "Chimie aromatique et test à l'eau de brome", ru: "Ароматические соединения и проба с бромной водой", ar: "المركبات العطرية واختبار ماء البروم", zh: "芳香族化合物与溴水褪色鉴别特征反应", ku: "Pêkhateyên Aromadîk û Ceribandina bi Ava Bromê" },
        quickHint: { tr: "Aromatik Bileşikler ve Bromlu Su Testi", en: "Aromatic Chemistry & Bromine Water Reaction Test", de: "Aromatische Chemie und Bromwassertest", fr: "Chimie aromatique et test à l'eau de brome", ru: "Ароматические соединения и проба с бромной водой", ar: "المركبات العطرية واختبار ماء البروم", zh: "芳香族化合物与溴水褪色鉴别特征反应", ku: "Pêkhateyên Aromadîk û Ceribandina bi Ava Bromê" },
        osymExamFact: { tr: "ÖSYM Ayıraç Tuzağı: Alkenler ve alkinler bromlu suyun rengini oda koşullarında katılarak GİDERİR; benzen ise bromlu suyun rengini GİDERMEZ! ÖSYM organik soru köklerinde bu ayıraç farkını hidrokarbon sınıfını tespit etmek için kilit ipucu olarak verir.", en: "Bromine Water Diagnostic Trap: Alkenes and alkynes rapidly decolorize bromine water via addition at room temperature; BENZENE DOES NOT decolorize bromine water! This test distinguishes aliphatic unsaturated hydrocarbons from aromatic rings.", de: "Diagnostischer Prüfungsfakt: Alkene und Alkine entfärben Bromwasser sofort; BENZOL ENT FÄRBT ES NICHT!", fr: "Différenciation d'examen : Alcènes et alcynes décolorent l'eau de brome instantanément ; LE BENZÈNE NE LA DÉCOLORE PAS !", ru: "Диагностический признак экзамена: Алкены и алкины обесцвечивают бромную воду; БЕНЗОЛ НЕ ОБЕСЦВЕЧИВАЕТ БРОМНУЮ ВОДУ!", ar: "فخ امتحاني تشخيصي: الألكينات والألكاينات تزيل لون ماء البروم سريعاً بتفاعل الإضافة؛ بينما البنزين لا يزيل لون ماء البروم مطلقاً في هذه الظروف!", zh: "高考有机化合物鉴别核心路标考点：含有碳碳双键或三键的脂肪族不饱和烃（烯烃、炔烃）在常温常压下极易与溴发生加成反应使溴水完全褪色；而苯分子由于大π键超常稳定性，常温下绝不使溴水褪色！这是高考推断题识别苯环的绝对关键标志！", ku: "Xefika Naskirina YKS: Alken û alkîn di germahiya odeyê de ava bromê bêreng dikin; lê benzen AVA BROMÊ BÊRENG NAKE!" },
      }
